#!/usr/bin/env node
// OMP Documenter self-contained installer. Writes only to a new destination.
// No network requests, subprocesses, package installation or OMP configuration changes.
import fs from "node:fs";
import path from "node:path";
import os from "node:os";
import crypto from "node:crypto";

const distribution = {"name":"omp-documenter","version":"1.0.0","files":[{"path":".gitignore","mode":420,"sha256":"147f739f03a238478aa7bae96b8e07d3be3a5c5313333af5911819c1f97471d2","base64":"bm9kZV9tb2R1bGVzLwouZG9jdW1lbnRlci8KY292ZXJhZ2UvCioubG9nCg=="},{"path":"CHANGELOG.md","mode":420,"sha256":"e2948cac4cea3f6d72f997a35facdf0bb3fe74b1a5ae2329866b9face766a583","base64":""},{"path":"docs/ARCHITECTURE.md","mode":420,"sha256":"bfd79b65df0e0c148fe2b81bdfd0b85b937382e772fb7ac96940d980042ea256","base64":""},{"path":"docs/ENGINE.md","mode":420,"sha256":"7b3326d959fcdedca41357a3fb1e6f2c399f6b00e9113f94779b9d3d8eb6456a","base64":""},{"path":"docs/ROADMAP.md","mode":420,"sha256":"8ac85c2ebb612e5a1650206bea0db01f9233775bc004c9fae183d27aa721c7a1","base64":""},{"path":"docs/USER-GUIDE.md","mode":420,"sha256":"aa3968dd0415a74218116b5c2617416386423591a342fecc10d365bb28b55c28","base64":""},{"path":"docs/VALIDATION.md","mode":420,"sha256":"3f2c691225c0e06c424c4c28e190bbf8271249f589bc6ee23225842a6e908250","base64":""},{"path":"lib/engine.mjs","mode":420,"sha256":"95ad1f0498420a821a9674afecd51daa227be9aac0486918873f632f1166dc57","base64":""},{"path":"package.json","mode":420,"sha256":"3c065641bd29373a6064612fc3bcd55c16f6ac0a5dadc0e61437dab5a27335ae","base64":""},{"path":"README.md","mode":420,"sha256":"7697ecf0707bd528cda0ac519b882f2a41b57c68d6bdd93e1608657a9f19a4c1","base64":""},{"path":"scripts/build-distribution.mjs","mode":493,"sha256":"31ec173e62d3409af382694af810256eec7065571721a07184bca1ed5e58ab6f","base64":""},{"path":"scripts/documenter.mjs","mode":493,"sha256":"02266282c3f0dac9aeb7272593de72c1e62a5f10320a3bb54a5ba1014540a0aa","base64":""},{"path":"skills/omp-documenter/references/coverage.md","mode":420,"sha256":"8ca5cb946521d30c8edf7da6864b5f392e6dbf4b7768b604a1b764bc1a62bcb5","base64":""},{"path":"skills/omp-documenter/references/evidence.md","mode":420,"sha256":"bd69120c6cf7f64e7d65af96c86e2acc1ef4dd598dc3bc7d37279c6def9062f6","base64":""},{"path":"skills/omp-documenter/references/maintenance.md","mode":420,"sha256":"72b33e35b0dd9baf5b35acdcd3035f5b6a8607ceff52795e4ec26a633fcdeb92","base64":""},{"path":"skills/omp-documenter/references/operations.md","mode":420,"sha256":"d01eec97e65774330b2865018779ee143aa9adebbed17c2e7096be3fa7fe1409","base64":""},{"path":"skills/omp-documenter/references/parallel.md","mode":420,"sha256":"89ae8583af3dbf8182fbfd282ed10159daae8257869edb531ae6ee62bb914ad2","base64":""},{"path":"skills/omp-documenter/references/workflow.md","mode":420,"sha256":"6b29217f658f96a0438cb6767f69b5459f3f9e4a9de098edd27c3871bfafb962","base64":""},{"path":"skills/omp-documenter/references/writing-standard.md","mode":420,"sha256":"52ede41de890aa06a351db0c3401806538e9fcc7f930bd8d66e927b10fda395a","base64":""},{"path":"skills/omp-documenter/SKILL.md","mode":420,"sha256":"69b210edb228fe1fd549ad0daf85865ed8916b1aae8a4c4f773af85867031170","base64":""},{"path":"src/index.js","mode":420,"sha256":"4cf57c3ee0c370b32b44089c2b344b6a983553d1cc49aa4bea002f19425aa6d8","base64":""},{"path":"templates/chapter.md","mode":420,"sha256":"d82e8415bd099e15e0dadc9e1cd61b4f420e8ef1f176e66f8d1f99e3273daecb","base64":""},{"path":"templates/unknowns.md","mode":420,"sha256":"db018dc8fe572a36a4cf02195da6a5c2289c5f4ff6f75d563ba178e5f19fe67a","base64":""},{"path":"tests/cli.test.mjs","mode":420,"sha256":"55337b5c67e08ab78528b436fe76749d09af5cc44c970da6be4996b0dfb5d2df","base64":""},{"path":"tests/distribution.test.mjs","mode":420,"sha256":"72dbcd7ae1766ed6b98daea92a5b77796c51e989b4ba2c5a4c43a7dd6779da67","base64":""},{"path":"tests/engine.test.mjs","mode":420,"sha256":"a5c6aa6cd498d9b7cfca2f8beea1d8afbcb91f90f46edcb2248af322ef0c7264","base64":""},{"path":"tests/extension.test.mjs","mode":420,"sha256":"cb0d127d742ce42058da0d494a851df813b25b22bccc16341946abb5f0ee244d","base64":""}]};
const hash = value => crypto.createHash("sha256").update(value).digest("hex");

function ensureSafeParents(destination) {
  const parsed = path.parse(destination);
  let current = parsed.root;
  for (const part of path.relative(parsed.root, destination).split(path.sep)) {
    if (!part) continue;
    current = path.join(current, part);
    let stat;
    try { stat = fs.lstatSync(current); }
    catch (error) {
      if (error.code !== "ENOENT") throw error;
      fs.mkdirSync(current, { mode: 0o700 });
      stat = fs.lstatSync(current);
    }
    if (stat.isSymbolicLink() || !stat.isDirectory()) throw new Error("Destination parent must be a normal directory: " + current);
  }
}

try {
  const args = process.argv.slice(2);
  if (args.length === 1 && ["--help", "-h"].includes(args[0])) {
    process.stdout.write("Usage: node omp-documenter-" + distribution.version + "-install.mjs [new-destination-directory]\nWrites the full plugin into a new directory. No OMP settings are changed.\n");
  } else {
    if (args.length > 1) throw new Error("Expected at most one destination directory. Use --help.");
    const destination = path.resolve(args[0] || path.join(os.homedir(), ".local", "share", "omp-documenter-" + distribution.version));
    let exists = false;
    try { fs.lstatSync(destination); exists = true; } catch (error) { if (error.code !== "ENOENT") throw error; }
    if (exists) throw new Error("Destination already exists; no files were changed. Choose a new directory: " + destination);
    const seen = new Set();
    for (const file of distribution.files) {
      if (!file.path || file.path.startsWith("/") || file.path.includes("\\") || /^[A-Za-z]:/.test(file.path) || file.path.split("/").some(part => !part || part === "." || part === "..") || seen.has(file.path)) throw new Error("Invalid packaged path.");
      seen.add(file.path);
      if (hash(Buffer.from(file.base64, "base64")) !== file.sha256) throw new Error("Package content check failed: " + file.path);
    }
    ensureSafeParents(path.dirname(destination));
    fs.mkdirSync(destination, { mode: 0o700 });
    for (const file of distribution.files) {
      const absolute = path.join(destination, ...file.path.split("/"));
      ensureSafeParents(path.dirname(absolute));
      fs.writeFileSync(absolute, Buffer.from(file.base64, "base64"), { flag: "wx", mode: file.mode });
      if (hash(fs.readFileSync(absolute)) !== file.sha256) throw new Error("Installed content check failed: " + file.path);
    }
    process.stdout.write("Installed OMP Documenter " + distribution.version + " (" + distribution.files.length + " files) in:\n" + destination + "\n\nNext: run omp plugin link with this directory as its argument, then start OMP in your project and run /documenter initial.\n");
  }
} catch (error) {
  process.stderr.write("Documenter installer: " + error.message + "\n");
  process.exitCode = 1;
}
